M.ById = {}
for _, r in ipairs(M.RefineSkills) do
    M.ById[r.id] = r
end

M.RefinesByTarget = {}
for _, r in ipairs(M.RefineSkills) do
    if r.refineTargetId then
        M.RefinesByTarget[r.refineTargetId] = M.RefinesByTarget[r.refineTargetId] or {}
        table.insert(M.RefinesByTarget[r.refineTargetId], r)
    end
end

M.BoundCount = 0
M.UnboundCount = 0
for _, r in ipairs(M.RefineSkills) do
    if r.refineTargetId then M.BoundCount = M.BoundCount + 1 else M.UnboundCount = M.UnboundCount + 1 end
end

return M